64	
65	@RestController
66	@CrossOrigin(exposedHeaders = "errors, content-type")
67	@RequestMapping("/api")
68	public class OwnerRestControllerV1 implements OwnersApi {
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    /**
79	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
80	     * and a domain containing at least one dot, with no whitespace in any segment.
81	     */
82	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
83	
84	    /**
85	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
86	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
87	     */
88	    private static final int MAX_OWNERS_PER_CITY = 50;
89	
90	    /**
91	     * Maximum number of owners that may be registered on a single day (by registration date). A create
92	     * attempted once this many owners already carry today's registration date is rejected with a
93	     * 429 Too Many Requests.
94	     */
95	    private static final int MAX_OWNERS_PER_DAY = 100;
96	
97	    /**
98	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
99	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
100	     */
101	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
102	        "ST", "STREET",
103	        "RD", "ROAD",
104	        "AVE", "AVENUE");
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        validateRequiredFields(ownerFieldsDto);
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        requireDailyCapacity();
148	        requireCityHasCapacity(owner.getCity());
149	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
150	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
151	            joinHousehold(owner);
152	        } else {
153	            requireUniqueHousehold(owner.getLastName(), owner.getAddress());
154	        }
155	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
156	        requireUniqueTelephone(telephone);
157	        owner.setTelephone(telephone);
158	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
159	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
160	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
161	        this.clinicService.saveOwner(owner);
162	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
163	        headers.setLocation(UriComponentsBuilder.newInstance()
164	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
165	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
166	    }
167	
168	    /**
169	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry today's
170	     * registration date. Existing owners are counted by {@code registrationDate} equal to the server's
171	     * current date, before the new owner is saved, so the count reflects only the owners that existed
172	     * prior to this create.
173	     *
174	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
175	     *     registered today
176	     */
177	    private void requireDailyCapacity() {
178	        LocalDate today = LocalDate.now();
179	        long todayOwnerCount = this.clinicService.findAllOwners().stream()
180	            .filter(existing -> today.equals(existing.getRegistrationDate()))
181	            .count();
182	        if (todayOwnerCount >= MAX_OWNERS_PER_DAY) {
183	            throw new DailyOwnerLimitException(today);
184	        }
185	    }
186	
187	    /**
188	     * Rejects an owner whose city already contains the maximum allowed number of owners
189	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
190	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
191	     * create.
192	     *
193	     * @param city the city of the owner being created
194	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
195	     */
196	    private void requireCityHasCapacity(String city) {
197	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
198	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
199	            .count();
200	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
201	            throw new CityOwnerLimitException(city);
202	        }
203	    }
204	
205	    /**
206	     * Generates the customer code for a newly created owner, formatted
207	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
208	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
209	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
210	     * that city (e.g. {@code 'LON-SMI-0007'}).
211	     *
212	     * @param city the owner's city
213	     * @param lastName the owner's last name
214	     * @return the generated customer code
215	     */
216	    private String generateCustomerCode(String city, String lastName) {
217	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
218	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
219	        int sequence = (int) this.clinicService.findAllOwners().stream()
220	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
221	            .count() + 1;
222	        return String.format("%s-%s-%04d", city3, last3, sequence);
223	    }
224	
225	    /**
226	     * Counts the existing owners that already share the given first name and last name, compared
227	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
228	     * owners that existed prior to this create.
229	     *
230	     * @param firstName the first name of the owner being created
231	     * @param lastName the last name of the owner being created
232	     * @return the number of pre-existing namesakes
233	     */
234	    private int countNamesakes(String firstName, String lastName) {
235	        return (int) this.clinicService.findAllOwners().stream()
236	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
237	                && equalsIgnoreCase(existing.getLastName(), lastName))
238	            .count();
239	    }
240	
241	    /**
242	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
243	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
244	     *
245	     * @param a the first value, possibly {@code null}
246	     * @param b the second value, possibly {@code null}
247	     * @return whether the values are equal ignoring case
248	     */
249	    private boolean equalsIgnoreCase(String a, String b) {
250	        return a == null ? b == null : a.equalsIgnoreCase(b);
251	    }
252	
253	    /**
254	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
255	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
256	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
257	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
258	     *
259	     * @param ownerFieldsDto the submitted owner fields
260	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
261	     */
262	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
263	        List<String> invalidFields = new ArrayList<>();
264	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
265	            invalidFields.add("firstName");
266	        }
267	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
268	            invalidFields.add("lastName");
269	        }
270	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
271	            invalidFields.add("address");
272	        }
273	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
274	            invalidFields.add("city");
275	        }
276	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
277	            invalidFields.add("telephone");
278	        }
279	        if (!invalidFields.isEmpty()) {
280	            throw new InvalidOwnerFieldsException(invalidFields);
281	        }
282	    }
283	
284	    /**
285	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
286	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
287	     * what gets stored and returned.
288	     *
289	     * @param telephone the raw telephone value from the request
290	     * @return the normalized E.164 telephone number
291	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
292	     */
293	    private String normalizeTelephone(String telephone) {
294	        String e164 = toE164(telephone);
295	        if (e164 == null) {
296	            throw new InvalidOwnerFieldsException(List.of("telephone"));
297	        }
298	        return e164;
299	    }
300	
301	    /**
302	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
303	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
304	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
305	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
306	     * it contains 8 to 15 digits after the {@code '+'}.
307	     *
308	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
309	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
310	     *
311	     * @param telephone the raw telephone value, possibly {@code null}
312	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
313	     */
314	    private String toE164(String telephone) {
315	        if (telephone == null) {
316	            return null;
317	        }
318	        String cleaned = telephone.replaceAll("[ \\-()]", "");
319	        String digits;
320	        if (cleaned.startsWith("+")) {
321	            digits = cleaned.substring(1);
322	        } else {
323	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
324	            digits = "61" + national;
325	        }
326	        if (!digits.matches("[0-9]{8,15}")) {
327	            return null;
328	        }
329	        return "+" + digits;
330	    }
331	
332	    /**
333	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
334	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
335	     * and returned lower-cased.
336	     *
337	     * @param email the raw email value from the request, possibly {@code null}
338	     * @return the lower-cased email, or {@code null} when none was supplied
339	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
340	     */
341	    private String normalizeEmail(String email) {
342	        if (!StringUtils.hasText(email)) {
343	            return null;
344	        }
345	        String trimmed = email.trim();
346	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
347	            throw new InvalidOwnerFieldsException(List.of("email"));
348	        }
349	        return trimmed.toLowerCase(Locale.ROOT);
350	    }
351	
352	    /**
353	     * Rejects a telephone number whose E.164 form is already used by an existing owner. This enforces
354	     * that no two owners share the same E.164 telephone. Existing values are compared by their E.164
355	     * form; a stored value that cannot form a valid E.164 number is compared as-is.
356	     *
357	     * @param telephone the normalized (E.164) telephone of the owner being created
358	     * @throws DuplicateTelephoneException if another owner already has this E.164 telephone
359	     */
360	    private void requireUniqueTelephone(String telephone) {
361	        boolean inUse = this.clinicService.findAllOwners().stream()
362	            .map(Owner::getTelephone)
363	            .filter(existing -> existing != null)
364	            .map(existing -> {
365	                String e164 = toE164(existing);
366	                return e164 != null ? e164 : existing;
367	            })
368	            .anyMatch(telephone::equals);
369	        if (inUse) {
370	            throw new DuplicateTelephoneException(telephone);
371	        }
372	    }
373	
374	    /**
375	     * Rejects an owner whose last name and address match those of an existing owner, where both are
376	     * compared case-insensitively and with runs of whitespace collapsed to a single space (a shared
377	     * household). The caller skips this check when the request opts in via {@code sharesHousehold}.
378	     *
379	     * @param lastName the last name of the owner being created
380	     * @param address the address of the owner being created
381	     * @throws DuplicateHouseholdException if another owner shares the same last name and address
382	     */
383	    private void requireUniqueHousehold(String lastName, String address) {
384	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
385	            throw new DuplicateHouseholdException(lastName, address);
386	        }
387	    }
388	
389	    /**
390	     * Returns the existing owners that belong to the same household as the given last name and
391	     * address, i.e. those whose last name and address match case-insensitively and with runs of
392	     * whitespace collapsed to a single space.
393	     *
394	     * @param lastName the last name to match
395	     * @param address the address to match
396	     * @return the matching owners (possibly empty, never {@code null})
397	     */
398	    private List<Owner> findHouseholdMembers(String lastName, String address) {
399	        String normalizedLastName = normalizeForHousehold(lastName);
400	        String normalizedAddress = normalizeAddress(address);
401	        return this.clinicService.findAllOwners().stream()
402	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
403	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
404	            .toList();
405	    }
406	
407	    /**
408	     * Joins the owner being created to the shared household of any existing owner(s) that have the
409	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
410	     * member of the household - the existing owners and the new one - is assigned the same stable
411	     * {@code householdId}, so the shared identifier can be read back from any of them.
412	     *
413	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
414	     * the owner is left without a {@code householdId}.
415	     *
416	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
417	     */
418	    private void joinHousehold(Owner owner) {
419	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
420	        if (members.isEmpty()) {
421	            return;
422	        }
423	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
424	        owner.setHouseholdId(householdId);
425	        for (Owner member : members) {
426	            if (!householdId.equals(member.getHouseholdId())) {
427	                member.setHouseholdId(householdId);
428	                this.clinicService.saveOwner(member);
429	            }
430	        }
431	    }
432	
433	    /**
434	     * Computes the stable, shared household identifier for a last name and address. The value is
435	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
436	     * name and address, so every owner in the same household computes the same identifier.
437	     *
438	     * @param lastName the last name of the household
439	     * @param address the address of the household
440	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
441	     */
442	    private String computeHouseholdId(String lastName, String address) {
443	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
444	        try {
445	            byte[] digest = MessageDigest.getInstance("SHA-256")
446	                .digest(key.getBytes(StandardCharsets.UTF_8));
447	            StringBuilder hex = new StringBuilder();
448	            for (int i = 0; i < 6; i++) {
449	                hex.append(String.format("%02X", digest[i]));
450	            }
451	            return "HH-" + hex;
452	        } catch (NoSuchAlgorithmException e) {
453	            throw new IllegalStateException("SHA-256 algorithm not available", e);
454	        }
455	    }
456	
457	    /**
458	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
459	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
460	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
461	     *
462	     * @param value the raw value, possibly {@code null}
463	     * @return the normalized value
464	     */
465	    private String normalizeForHousehold(String value) {
466	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
467	    }
468	
469	    /**
470	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
471	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
472	     * value yields an empty string.
473	     *
474	     * @param value the raw value, possibly {@code null}
475	     * @return the trimmed, whitespace-collapsed value
476	     */
477	    private String collapseWhitespace(String value) {
478	        if (value == null) {
479	            return "";
480	        }
481	        return value.trim().replaceAll("\\s+", " ");
482	    }
483	
484	    /**
485	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
486	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
487	     * is upper-cased, and common street-type abbreviations are expanded as whole words
488	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
489	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
490	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
491	     *
492	     * @param address the raw address value, possibly {@code null}
493	     * @return the normalized address
494	     */
495	    private String normalizeAddress(String address) {
496	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
497	        if (collapsed.isEmpty()) {
498	            return "";
499	        }
500	        String[] tokens = collapsed.split(" ");
501	        StringBuilder normalized = new StringBuilder();
502	        for (int i = 0; i < tokens.length; i++) {
503	            if (i > 0) {
504	                normalized.append(' ');
505	            }
506	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
507	        }
508	        return normalized.toString();
509	    }
510	
511	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
512	    @Override
513	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
514	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
515	        if (currentOwner == null) {
516	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
517	        }
518	        currentOwner.setAddress(ownerFieldsDto.getAddress());
519	        currentOwner.setCity(ownerFieldsDto.getCity());
520	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
521	        currentOwner.setLastName(ownerFieldsDto.getLastName());
522	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
523	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
524	        this.clinicService.saveOwner(currentOwner);
525	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
526	    }
527	
528	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
529	    @Transactional
530	    @Override
531	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
532	        Owner owner = this.clinicService.findOwnerById(ownerId);
533	        if (owner == null) {
534	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
535	        }
536	        this.clinicService.deleteOwner(owner);
537	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
538	    }
