540	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
541	    @Override
542	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
543	        Owner owner = this.clinicService.findOwnerById(ownerId);
544	        if (owner == null) {
545	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
546	        }
547	        HttpHeaders headers = new HttpHeaders();
548	        Pet pet = petMapper.toPet(petFieldsDto);
549	        owner.setId(ownerId);
550	        pet.setOwner(owner);
551	        pet.getType().setName(null);
552	        this.clinicService.savePet(pet);
553	        PetDto petDto = petMapper.toPetDto(pet);
554	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
555	            .buildAndExpand(pet.getId()).toUri());
556	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
557	    }
558	
559	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
560	    @Override
561	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
562	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
563	        if (currentOwner != null) {
564	            Pet currentPet = this.clinicService.findPetById(petId);
565	            if (currentPet != null) {
566	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
567	                currentPet.setName(petFieldsDto.getName());
568	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
569	                this.clinicService.savePet(currentPet);
570	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
571	            }
572	        }
573	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
574	    }
575	
576	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
