/**
 * Defaults the registration date to the server's current date when none was supplied,
 * so every newly persisted owner is stamped exactly once on insert, then rolls the
 * effective date forward to a business day so no owner is ever registered on a weekend.
 */
@PrePersist
void onCreate() {
    if (this.registrationDate == null) {
        this.registrationDate = LocalDate.now();
    }
    this.registrationDate = toBusinessDay(this.registrationDate);
}

/**
 * Rolls a registration date forward onto a business day: a Saturday or Sunday becomes the
 * following Monday, while any weekday is returned unchanged. This is the single definition of
 * the business-day rule, applied to the effective registration date whether it was supplied in
 * the request or defaulted to the server's current date.
 *
 * @param date the effective registration date
 * @return the date itself when it is a weekday, otherwise the next Monday
 */
public static LocalDate toBusinessDay(LocalDate date) {
    return switch (date.getDayOfWeek()) {
        case SATURDAY -> date.plusDays(2);
        case SUNDAY -> date.plusDays(1);
        default -> date;
    };
}

